export interface SampleQuestion {
  id: string
  page: number
  prompt: string
  options: [string, string, string, string]
  answer: 0 | 1 | 2 | 3
  /** Source passage around the answer; `highlight` is the sentence that supports it. */
  passage: { before: string; highlight: string; after: string }
}

